import { readdirSync, readFileSync, mkdirSync, writeFileSync, existsSync, renameSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sourceRoot = path.resolve(appRoot, '../../data/real-world');
const output = path.join(appRoot, 'lib/gameWorld/generated/realWorldFiles.ts');
const files = {};

function visit(directory) {
  const entries = readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0);
  for (const entry of entries) {
    const filename = path.join(directory, entry.name);
    if (entry.isDirectory()) visit(filename);
    else if (entry.isFile() && entry.name.endsWith('.json')) {
      // Parse at build time: malformed canonical JSON must fail the build.
      const key = path.relative(sourceRoot, filename).split(path.sep).join('/');
      files[key] = JSON.stringify(JSON.parse(readFileSync(filename, 'utf8')));
    }
  }
}

visit(sourceRoot);
if (!Object.keys(files).length) throw new Error('Kunde inte paketera spelartrupper: datakällan är tom.');
mkdirSync(path.dirname(output), { recursive: true });
const source = `// Generated by scripts/generate-real-world-bundle.mjs. Server-only; do not edit.\nconst files: Record<string, string> = ${JSON.stringify(files)};\nexport default files;\n`;
if (!existsSync(output) || readFileSync(output, 'utf8') !== source) {
  const temporary = `${output}.${process.pid}.tmp`;
  writeFileSync(temporary, source);
  renameSync(temporary, output);
}
console.log(`Bundled ${Object.keys(files).length} canonical real-world JSON files.`);
